   work.innerHTML='<div class="admin-module"><div class="admin-module-head"><div><span class="admin-kicker">'+(tab==="creators"?"CREATOR NETWORK":"GUEST NETWORK")+'</span><h3>'+title+'</h3><p>Directory view. Member account roles are managed separately in the Members section.</p></div><input class="admin-search" id="adminSearch" placeholder="Search records…" aria-label="Search records"></div>'+(rows.length?table(["Record",...columns.slice(1).map(x=>x.replaceAll("_"," "))],rows.map(x=>'<tr data-search-row="'+esc(Object.values(x).filter(v=>typeof v!=="object").join(" "))+'"><td><b>'+esc(x.display_name||x.id||"Profile")+'</b></td>'+columns.slice(1).map(c=>'<td>'+esc(Array.isArray(x[c])?x[c].join(", "):x[c]??"—")+'</td>').join("")+'</tr>').join("")):empty)+'</div>';
   $("#adminSearch")?.addEventListener("input",e=>all("[data-search-row]").forEach(row=>row.hidden=!row.dataset.searchRow.toLowerCase().includes(e.target.value.toLowerCase())));return;
