async function subs(){let u=await me();if(!u)return go("login.html");$("#app").innerHTML='<section class="page-hero"><div class="container"><div class="eyebrow">Account</div><h1 class="page-title">Your memberships</h1><p>Manage show subscriptions and your CrowRules platform membership.</p></div></section><section class="section container"><div class="panel"><div class="section-head"><h3>Podcast show subscriptions</h3><button id="showPortal" class="secondary">Manage show billing</button></div><div id="subscriptionRows" class="loading">Loading your subscriptions…</div></div><div class="panel"><h3>CrowRules platform membership</h3><p class="muted">Your platform membership is separate from individual show subscriptions.</p><button id="platformPortal">Manage platform billing</button></div></section>';try{let d=await fn(FUNCTIONS.subscriptionCenter,{origin:location.origin+SITE_BASE}),rows=d.subscriptions||[],ids=[...new Set(rows.map(x=>x.podcast_id).filter(Boolean))],{data:ps}=ids.length?await sb.from("podcasts").select("id,title").in("id",ids):{data:[]};$("#subscriptionRows").innerHTML=rows.length?'<div class="table-wrap"><table><thead><tr><th>Show</th><th>Status</th><th>Amount</th><th>Renewal / end</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(ps?.find(p=>p.id===x.podcast_id)?.title||"Podcast membership")+'</td><td>'+esc(x.status)+(x.cancel_at_period_end?" · Cancels at period end":"")+'</td><td>'+Number(x.amount_cents||0)/100+' '+esc((x.currency||"USD").toUpperCase())+'</td><td>'+(x.current_period_end?new Date(x.current_period_end).toLocaleDateString():"—")+'</td></tr>').join("")+'</tbody></table></div>':'<div class="empty">You do not have any podcast show subscriptions yet.</div>';$("#showPortal").disabled=!d.portal_url;$("#showPortal").onclick=()=>{if(d.portal_url)location.href=d.portal_url}}catch(e){$("#subscriptionRows").innerHTML='<div class="notice">'+esc(e.message)+'</div>'}$("#platformPortal").onclick=async()=>{try{let d=await fn(FUNCTIONS.billingPortal,{});if(d.url)location.href=d.url}catch(e){toast(e.message)}}}async function renderCurrentPage(){updateLivePresenceRole();if(page==="home")return home();if(page==="discover")return discover();if(page==="show")return show();if(page==="episode")return episode();if(page==="login"||page==="signup")return auth();if(page==="creator")return creator();if(page==="listener")return listener();if(page==="guest")return guest();if(page==="rankings")return rankings();if(page==="awards")return awards();if(page==="admin")return admin();if(page==="subscriptions")return subs();return home()}async function init(){shell();enableSeamlessNavigation();return renderCurrentPage()}init().catch(e=>{console.error(e);$("#app").innerHTML='<div class="container section notice">'+esc(e.message)+'</div>'});
